115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        if (!normalizeAndValidateFields(owner)) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
123	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
127	        owner.setRegistrationDate(registrationDate);
128	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
129	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
130	        }
131	        owner.setIdentityKey(identityKey(owner));
132	        if (isDuplicate(owner)) {
133	            return new ResponseEntity<>(HttpStatus.CONFLICT);
134	        }
135	        if (countOwnersInCity(owner.getCity()) >= 50) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        assignRegistrationAttributes(owner);
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
141	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
142	        HttpHeaders headers = new HttpHeaders();
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
146	    }
