148	    /**
149	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
150	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
151	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
152	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
153	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
154	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
155	     */
156	    private boolean normalizeAndValidateFields(Owner owner) {
157	        String address = normalizeAddress(owner.getAddress());
158	        if (address.isEmpty()) {
159	            return false;
160	        }
161	        owner.setAddress(address);
162	        if (owner.getEmail() != null) {
163	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
164	            if (!EMAIL_PATTERN.matcher(email).matches()) {
165	                return false;
166	            }
167	            owner.setEmail(email);
168	        }
169	        if (!isPostcodeValidForCity(owner)) {
170	            return false;
171	        }
172	        String telephone = normalizeTelephone(owner.getTelephone());
173	        if (telephone == null) {
174	            return false;
175	        }
176	        owner.setTelephone(telephone);
177	        return true;
178	    }
