293	    /** Matches a well-formed postcode: exactly 4 digits. */
294	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
295	
296	    /**
297	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
298	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
299	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
300	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
301	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
302	     */
303	    private static boolean isPostcodeValidForCity(Owner owner) {
304	        String postcode = owner.getPostcode();
305	        if (postcode == null) {
306	            return true;
307	        }
308	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
309	            return false;
310	        }
311	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
312	        if (range == null) {
313	            return true;
314	        }
315	        int value = Integer.parseInt(postcode);
316	        return value >= range[0] && value <= range[1];
317	    }
318	
319	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
320	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
321	
322	    /**
323	     * Required national-number length per country code: '+61' (Australia) expects 9 national
324	     * digits and '+1' (NANP) expects 10. A number whose country code is listed here but whose
325	     * national part is not the required length is rejected.
326	     */
327	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
328	        "+61", 9, "+1", 10);
329	
330	    /**
331	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
332	     * code are kept when present; otherwise country code '+61' is assumed and a single
333	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
334	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
335	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
336	     * Returns {@code null} when the number cannot form a valid E.164 value.
337	     */
338	    private static String normalizeTelephone(String telephone) {
339	        if (telephone == null) {
340	            return null;
341	        }
342	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
343	        String e164;
344	        if (cleaned.startsWith("+")) {
345	            e164 = cleaned;
346	        } else {
347	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
348	            e164 = "+61" + national;
349	        }
350	        if (!E164_PATTERN.matcher(e164).matches()) {
351	            return null;
352	        }
353	        return hasValidNationalNumberLength(e164) ? e164 : null;
354	    }
355	
356	    /**
357	     * Whether the national number of a well-formed E.164 value has the length required for its
358	     * country code. Country codes not listed in {@link #NATIONAL_NUMBER_LENGTHS} carry no
359	     * per-country length rule and are accepted.
360	     */
361	    private static boolean hasValidNationalNumberLength(String e164) {
362	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
363	            String countryCode = entry.getKey();
364	            if (e164.startsWith(countryCode)) {
365	                return e164.length() - countryCode.length() == entry.getValue();
366	            }
367	        }
368	        return true;
369	    }
370	
371	    /**
372	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
373	     * code, membership number, household id, namesake count and household member count. Each is
374	     * derived from the owner's already-normalized fields and the existing owner population, so this
375	     * must run before the owner is saved, while the counts still exclude the owner being created.
376	     */
377	    private void assignRegistrationAttributes(Owner owner) {
378	        owner.setCustomerCode(generateCustomerCode(owner));
379	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
380	        owner.setHouseholdId(householdId(owner));
381	        owner.setNamesakeCount(countNamesakes(owner));
382	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
383	    }
384	
385	    /**
386	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
387	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
388	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
389	     * owner's last name (e.g. 'NSW-1A2B3C4D'). There are no sequence numbers: the identity is a pure
390	     * function of the region and the (telephone, last name) pair.
391	     */
392	    private String generateCustomerCode(Owner owner) {
393	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
394	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
395	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
396	        return owner.getRegion() + "-" + hash8;
397	    }
398	
399	    /**
400	     * The number of existing owners registered in {@code city}, compared case-insensitively
401	     * with collapsed whitespace.
402	     */
403	    private int countOwnersInCity(String city) {
404	        String normalized = normalizeHouseholdField(city);
405	        return (int) this.clinicService.findAllOwners().stream()
406	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
407	            .count();
408	    }
409	
410	    /**
411	     * The effective registration date to store for a new owner: the date supplied on the request
412	     * when present, otherwise the current server date, in either case rolled forward to a business
413	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
414	     * This single point of resolution is what every registration-date-derived value (the stored
415	     * date, the membership number's year segment, the per-day create-limit) is computed from.
416	     */
417	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
418	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
419	        return toBusinessDay(date);
420	    }
421	
422	    /**
423	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
424	     * following Monday; a weekday is returned unchanged.
425	     */
426	    private static LocalDate toBusinessDay(LocalDate date) {
427	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
428	            date = date.plusDays(1);
429	        }
430	        return date;
431	    }
432	
433	    /**
434	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
435	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
436	     */
437	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
438	        String yy = String.format("%02d", registrationDate.getYear() % 100);
439	        return customerCode + "-M" + yy;
440	    }
441	
442	    /**
443	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
444	     * last name, compared case-insensitively.
445	     */
446	    private int countNamesakes(Owner owner) {
447	        String firstName = normalizeHouseholdField(owner.getFirstName());
448	        String lastName = normalizeHouseholdField(owner.getLastName());
449	        return (int) this.clinicService.findAllOwners().stream()
450	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
451	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
452	            .count();
453	    }
454	
455	    /**
456	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
457	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
458	     * unusually high daily signup volume.
459	     */
460	    private boolean isBulkSignupWarning() {
461	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
462	    }
463	
464	    /** The number of existing owners whose registration date is {@code date}. */
465	    private int countOwnersRegisteredOn(LocalDate date) {
466	        return (int) this.clinicService.findAllOwners().stream()
467	            .filter(existing -> date.equals(existing.getRegistrationDate()))
468	            .count();
469	    }
470	
471	    /**
472	     * The single derived key all duplicate detection flows through, formed from the owner's
473	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
474	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
475	     * id is derived, so the household segment is empty at that point. Because the telephone is part
476	     * of the key, two owners in the same household with different telephones resolve to different
477	     * keys and are both allowed.
478	     */
479	    private static String identityKey(Owner owner) {
480	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
481	        String email = owner.getEmail() == null ? "" : owner.getEmail();
482	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
483	        return telephone + "|" + email + "|" + household;
484	    }
485	
486	    /**
487	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
488	     * duplicate condition: the previously separate telephone, email and household checks are now all
489	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
490	     * trips it is rejected with {@code 409 CONFLICT}.
491	     */
492	    private boolean isDuplicate(Owner owner) {
493	        String key = owner.getIdentityKey();
494	        return this.clinicService.findAllOwners().stream()
495	            .map(Owner::getIdentityKey)
496	            .filter(existing -> existing != null)
497	            .anyMatch(key::equals);
498	    }
499	
500	    /** Common street-type abbreviations expanded during address normalization. */
501	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
502	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
503	
504	    /**
505	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
506	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
507	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
508	     * string when {@code address} is null or blank after normalization.
509	     */
510	    private static String normalizeAddress(String address) {
511	        if (address == null) {
512	            return "";
513	        }
514	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
515	        if (collapsed.isEmpty()) {
516	            return "";
517	        }
518	        StringBuilder sb = new StringBuilder(collapsed.length());
519	        for (String token : collapsed.split(" ")) {
520	            if (sb.length() > 0) {
521	                sb.append(' ');
522	            }
523	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
524	        }
525	        return sb.toString();
526	    }
527	
528	    /**
529	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
530	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
531	     */
532	    private static String normalizeHouseholdField(String value) {
533	        if (value == null) {
534	            return "";
535	        }
536	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
537	    }
538	
539	    /**
540	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
541	     * same address compared case-insensitively with collapsed whitespace.
542	     */
543	    private List<Owner> findHousemates(Owner owner) {
544	        String lastName = normalizeHouseholdField(owner.getLastName());
545	        String address = normalizeHouseholdField(owner.getAddress());
546	        return this.clinicService.findAllOwners().stream()
547	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
548	                && normalizeHouseholdField(existing.getAddress()).equals(address))
549	            .toList();
550	    }
551	
552	    /**
553	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
554	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
555	     */
556	    private int countHouseholdMembers(Owner owner) {
557	        return findHousemates(owner).size() + 1;
558	    }
559	
560	    /**
561	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
562	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
563	     * deterministically from those normalized fields so housemates always resolve to the same value,
564	     * regardless of registration order.
565	     */
566	    private static String householdId(Owner owner) {
567	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
568	            + normalizeHouseholdField(owner.getAddress());
569	        return sha256Hex(key).substring(0, 24);
570	    }
571	
572	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
573	    private static String sha256Hex(String input) {
574	        try {
575	            byte[] digest = MessageDigest.getInstance("SHA-256")
576	                .digest(input.getBytes(StandardCharsets.UTF_8));
577	            StringBuilder sb = new StringBuilder(digest.length * 2);
578	            for (byte b : digest) {
579	                sb.append(String.format("%02X", b));
580	            }
581	            return sb.toString();
582	        }
583	        catch (NoSuchAlgorithmException e) {
584	            throw new IllegalStateException("SHA-256 not available", e);
585	        }
586	    }
587	}
